const MAX_TEXT:usize=24;
fn mul(a:u16,b:u16)->u16{let x=if a==0{65536u64}else{a as u64};let y=if b==0{65536u64}else{b as u64};let z=(x*y)%65537;if z==65536{0}else{z as u16}}
fn expand(key:&[u8;16])->[u16;52]{let mut s=[0u16;8];for i in 0..8{s[i]=u16::from_be_bytes([key[2*i],key[2*i+1]])}let mut z=[0u16;52];let mut off=0;while off<52{let n=(52-off).min(8);z[off..off+n].copy_from_slice(&s[..n]);let mut r=[0u16;8];for i in 0..8{r[i]=s[(i+1)&7].wrapping_shl(9)|s[(i+2)&7]>>7}s=r;off+=8;}z}
fn encrypt(z:&[u16;52],input:&[u8;8])->[u8;8]{let mut x1=u16::from_be_bytes([input[0],input[1]]);let mut x2=u16::from_be_bytes([input[2],input[3]]);let mut x3=u16::from_be_bytes([input[4],input[5]]);let mut x4=u16::from_be_bytes([input[6],input[7]]);for r in 0..8{let k=&z[r*6..r*6+6];let a=mul(x1,k[0]);let b=x2.wrapping_add(k[1]);let c=x3.wrapping_add(k[2]);let d=mul(x4,k[3]);let p=mul(a^c,k[4]);let q=mul((b^d).wrapping_add(p),k[5]);let t=p.wrapping_add(q);x1=a^q;x2=c^q;x3=b^t;x4=d^t;}let y=[mul(x1,z[48]),x3.wrapping_add(z[49]),x2.wrapping_add(z[50]),mul(x4,z[51])];let mut out=[0u8;8];for i in 0..4{out[2*i..2*i+2].copy_from_slice(&y[i].to_be_bytes())}out}
fn put(out:*mut u8,bytes:&[u8]){for(i,b)in bytes.iter().enumerate(){unsafe{*out.add(i)=*b}}}
#[no_mangle]
pub unsafe extern "C" fn idea_cfb64(raw:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if raw.is_null()||n<27||n>51{return -1}let v=unsafe{std::slice::from_raw_parts(raw,n)};let mode=v[0];let len=v[1];if !(0..=1).contains(&mode)||!(1..=MAX_TEXT as i64).contains(&len)||n!=26+len as usize{return -1}let mut key=[0u8;16];let mut state=[0u8;8];for i in 0..16{if !(0..=255).contains(&v[2+i]){return -1}key[i]=v[2+i] as u8}for i in 0..8{if !(0..=255).contains(&v[18+i]){return -1}state[i]=v[18+i] as u8}let mut text=[0u8;MAX_TEXT];for i in 0..len as usize{if !(0..=255).contains(&v[26+i]){return -1}text[i]=v[26+i] as u8}let z=expand(&key);let mut result=[0u8;MAX_TEXT];let mut pos=0;while pos<len as usize{let stream=encrypt(&z,&state);let take=(len as usize-pos).min(8);for j in 0..take{result[pos+j]=text[pos+j]^stream[j];state[j]=if mode==0{result[pos+j]}else{text[pos+j]}}pos+=take}if out.is_null()||cap<len as usize{return -2}put(out,&result[..len as usize]);len}
